text:
{
  "design": {
    "theme": "chalk",
    "picture_style": "photo"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall names of familiar adult animals",
      "look_at": {
        "kind": "picture",
        "shows": "A cow, sheep, hen and dog"
      },
      "teaches": [1]
    },
    {
      "slide": 2,
      "does": "Introduce the learning goals",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Model naming two adult–young pairs",
      "look_at": {
        "kind": "picture",
        "shows": "A cow beside a calf and a sheep beside a lamb"
      },
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Try matching cows, calves, sheep and lambs",
      "look_at": {
        "kind": "picture",
        "shows": "Four separated animals to match"
      },
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Model naming two more adult–young pairs",
      "look_at": {
        "kind": "picture",
        "shows": "A hen beside a chick and a dog beside a puppy"
      },
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Try matching hens, chicks, dogs and puppies",
      "look_at": {
        "kind": "picture",
        "shows": "Four separated animals to match"
      },
      "teaches": [1]
    },
    {
      "slide": 7,
      "does": "Predict changes as a chick grows",
      "look_at": {
        "kind": "picture",
        "shows": "A small, downy chick"
      },
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Teach growth and adult feather development",
      "look_at": {
        "kind": "picture-sequence",
        "shows": "A female chick growing into an adult hen"
      },
      "teaches": [2]
    },
    {
      "slide": 9,
      "does": "Model describing two changes",
      "look_at": {
        "kind": "picture",
        "shows": "A chick and hen at the same scale"
      },
      "teaches": [2]
    },
    {
      "slide": 10,
      "does": "Try describing the same two changes",
      "look_at": {
        "kind": "picture",
        "shows": "Another chick and hen at the same scale"
      },
      "teaches": [2]
    },
    {
      "slide": 11,
      "does": "Correct the idea that a hen is just a bigger fluffy chick",
      "look_at": {
        "kind": "picture",
        "shows": "Downy chick covering compared with adult hen feathers"
      },
      "teaches": [2]
    },
    {
      "slide": 12,
      "does": "Apply learning to a growing bird, then complete the worksheet exit ticket",
      "look_at": {
        "kind": "picture",
        "shows": "An unfamiliar feathered young female chicken"
      },
      "teaches": [1, 2]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Animals and their young",
    "lead": "Name the animals. What do you remember?",
    "picture": {
      "shows": "Four separate photographs of familiar adult animals",
      "must_see": [
        "adult cow",
        "adult sheep",
        "adult hen",
        "adult dog"
      ],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "compare",
      "heading": "Adults and their young",
      "columns": [
        {
          "label": "Cow and calf",
          "text": "A young cow is a calf.",
          "picture": {
            "shows": "An adult cow standing beside its young calf",
            "must_see": [
              "adult cow",
              "small calf"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "Sheep and lamb",
          "text": "A young sheep is a lamb.",
          "picture": {
            "shows": "An adult sheep standing beside its young lamb",
            "must_see": [
              "adult sheep",
              "small lamb"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "question-set",
      "heading": "Find the pairs",
      "questions": [
        "Which young animal goes with the cow?",
        "Which young animal goes with the sheep?",
        "What is each young animal called?"
      ],
      "instruction": "Point to each pair. Say the names.",
      "picture": {
        "shows": "Separate photographs in a two-by-two arrangement: cow top left, lamb top right, sheep bottom left, calf bottom right, without connecting lines",
        "must_see": [
          "adult cow",
          "small lamb",
          "adult sheep",
          "small calf"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "compare",
      "heading": "Two more pairs",
      "columns": [
        {
          "label": "Hen and chick",
          "text": "A young chicken is a chick.",
          "picture": {
            "shows": "An adult hen beside a small downy chick",
            "must_see": [
              "adult hen",
              "downy chick"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "Dog and puppy",
          "text": "A young dog is a puppy.",
          "picture": {
            "shows": "An adult dog beside a puppy of the same breed",
            "must_see": [
              "adult dog",
              "small puppy"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "question-set",
      "heading": "Find the pairs",
      "questions": [
        "Which young animal goes with the hen?",
        "Which young animal goes with the dog?",
        "What is each young animal called?"
      ],
      "instruction": "Point to each pair. Say the names.",
      "picture": {
        "shows": "Separate photographs in a two-by-two arrangement: puppy top left, hen top right, chick bottom left, dog bottom right, without connecting lines",
        "must_see": [
          "small puppy",
          "adult hen",
          "downy chick",
          "adult dog"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "discussion",
      "heading": "What might change?",
      "lead": "Tell your partner: how might this chick change as it grows?",
      "picture": {
        "shows": "A newly hatched female chick standing alone",
        "must_see": [
          "small chick",
          "soft fluffy down",
          "tiny wings"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "picture-sequence",
      "heading": "A chick grows into a hen",
      "sequence": [
        {
          "shows": "A newly hatched female chick with fluffy down and no developed adult wing or tail feathers, shown at the same scale as the later stages",
          "must_see": [
            "small body",
            "fluffy down",
            "tiny wings"
          ],
          "subject": "generic",
          "caption": "Small and fluffy"
        },
        {
          "shows": "A larger young female chicken with developing wing feathers and some remaining down, not yet the full adult plumage of the next stage",
          "must_see": [
            "larger body",
            "growing wing feathers",
            "some fluffy down"
          ],
          "subject": "generic",
          "caption": "Bigger; feathers grow"
        },
        {
          "shows": "A fully grown hen with adult body, wing and tail feathers, shown at the same scale as the earlier stages",
          "must_see": [
            "large adult body",
            "adult wing feathers",
            "adult tail feathers"
          ],
          "subject": "generic",
          "caption": "An adult hen"
        }
      ]
    },
    {
      "template": "visual-text",
      "heading": "Describe the changes",
      "lead": "This chick grows into a hen.",
      "points": [
        "It gets bigger.",
        "It grows adult feathers."
      ],
      "figure": {
        "shows": "A newly hatched female chick beside an adult hen of the same breed, photographed at the same scale",
        "must_see": [
          "small downy chick",
          "larger adult hen",
          "long wing feathers",
          "adult tail feathers"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "question-set",
      "heading": "Your turn",
      "questions": [
        "How does its size change?",
        "How does its feather covering change?"
      ],
      "instruction": "Describe two changes.",
      "picture": {
        "shows": "A newly hatched female chick and an adult hen of another breed, shown at the same scale without labels",
        "must_see": [
          "small fluffy chick",
          "large adult hen",
          "adult wing feathers",
          "adult tail feathers"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "compare",
      "heading": "More than getting bigger",
      "columns": [
        {
          "label": "Chick",
          "text": "Soft, fluffy down covers its body.",
          "picture": {
            "shows": "Close view of a newly hatched chick's fluffy body covering",
            "must_see": [
              "soft fluffy down",
              "small chick body"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "Hen",
          "text": "Adult feathers cover its body.",
          "picture": {
            "shows": "Close view of a hen with distinct overlapping body feathers and long wing feathers",
            "must_see": [
              "overlapping body feathers",
              "long wing feathers"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "question-set",
      "heading": "Look at this young bird",
      "questions": [
        "Is it newly hatched or older? How can you tell?",
        "What will change as it grows into a hen?"
      ],
      "instruction": "Look closely. Explain your ideas.",
      "picture": {
        "shows": "A partly grown female chicken of a breed not shown earlier, with developing wing feathers, patches of remaining down and an immature tail",
        "must_see": [
          "developing wing feathers",
          "remaining fluffy down",
          "short immature tail"
        ],
        "subject": "generic"
      }
    }
  ]
}
